$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host " PATCH 163A - HIGH-END BUKLOD GUIDE AVATAR" -ForegroundColor Cyan
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host ""

$projectRoot = (Get-Location).Path
$layoutPath = Join-Path $projectRoot "src\app\(tabs)\_layout.tsx"
$providerPath = Join-Path $projectRoot "src\providers\NotificationProvider.tsx"
$componentPath = Join-Path $projectRoot "src\components\BuklodGuideAvatar.tsx"
$assetDir = Join-Path $projectRoot "assets\buklod-guide"

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    $enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Text, $enc)
}

function Write-Base64File([string]$Path, [string]$Base64) {
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($Path, $bytes)
}

if (-not (Test-Path -LiteralPath $layoutPath)) {
    throw "PATCH 163A stopped: missing $layoutPath"
}

if (-not (Test-Path -LiteralPath $providerPath)) {
    throw "PATCH 163A stopped: NotificationProvider.tsx is missing."
}

$providerSource = Get-Content -LiteralPath $providerPath -Raw
if ($providerSource -notmatch "useNotifications") {
    throw "PATCH 163A stopped: useNotifications hook was not found."
}

if (-not (Test-Path -LiteralPath (Join-Path $projectRoot "node_modules\react-native-reanimated"))) {
    Write-Host "WARNING: node_modules\react-native-reanimated not found." -ForegroundColor Yellow
    Write-Host "The project previously used Reanimated. Run npm install first if node_modules is incomplete." -ForegroundColor Yellow
}

Write-Host "1/6 Baseline TypeScript check..." -ForegroundColor Yellow
npx tsc --noEmit
if ($LASTEXITCODE -ne 0) {
    throw "PATCH 163A stopped BEFORE changes: baseline TypeScript is not clean."
}

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$layoutBackup = "$layoutPath.before-PATCH-163A-$stamp"
Copy-Item -LiteralPath $layoutPath -Destination $layoutBackup -Force

$componentExisted = Test-Path -LiteralPath $componentPath
$componentBackup = "$componentPath.before-PATCH-163A-$stamp"
if ($componentExisted) {
    Copy-Item -LiteralPath $componentPath -Destination $componentBackup -Force
}

Write-Host "2/6 Installing optimized BUKLOD Guide poses..." -ForegroundColor Yellow

