Write-Base64File (Join-Path $assetDir "wave.png") $waveBase64
Write-Base64File (Join-Path $assetDir "celebrate.png") $celebrateBase64
Write-Base64File (Join-Path $assetDir "think.png") $thinkBase64

Write-Host "3/6 Installing reusable animated guide component..." -ForegroundColor Yellow

$componentSource = @'
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  AccessibilityInfo,
  Image,
  Pressable,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { router, usePathname } from 'expo-router';
import Animated, {
  Easing,
  cancelAnimation,
  useAnimatedStyle,
  useSharedValue,
  withDelay,
  withRepeat,
  withSequence,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { supabase } from '@/lib/supabase';
import { useNotifications } from '@/providers/NotificationProvider';

type Pose = 'wave' | 'celebrate' | 'think';

const GUIDE = {
  wave: require('../../assets/buklod-guide/wave.png'),
  celebrate: require('../../assets/buklod-guide/celebrate.png'),
  think: require('../../assets/buklod-guide/think.png'),
} as const;

function routePose(pathname: string): Pose {
  if (pathname.includes('prayer')) return 'think';
  return 'wave';
}

function routeMessage(pathname: string) {
  if (pathname.includes('prayer')) {
    return "I'm with you. Let's pray.";
  }
  if (pathname.includes('buklod')) {
    return 'Your community is active. Stay connected.';
  }
  if (pathname.includes('learn')) {
    return 'One lesson at a time. Keep growing.';
  }
  if (pathname.includes('word')) {
    return "Ready for today's Word?";
  }
  if (pathname.includes('me')) {
    return 'Your BUKLOD tools are all here.';
  }
  return "I'm here. Let's check what matters today.";
}

export function BuklodGuideAvatar() {
  const pathname = usePathname();
  const { unreadCount } = useNotifications();

  const basePose = useMemo(
    () => routePose(pathname),
    [pathname]
  );

  const [pose, setPose] = useState<Pose>(basePose);
  const [bubbleText, setBubbleText] = useState(
    routeMessage(pathname)
  );
  const [bubbleMounted, setBubbleMounted] =
    useState(true);
  const [reduceMotion, setReduceMotion] =
    useState(false);

  const previousUnread = useRef(unreadCount);
  const bubbleTimer = useRef<
    ReturnType<typeof setTimeout> | null
  >(null);
  const reactionTimer = useRef<
    ReturnType<typeof setTimeout> | null
  >(null);
  const lastRealtimeReaction = useRef(0);

  const entryOpacity = useSharedValue(0);
  const entryY = useSharedValue(22);
  const floatY = useSharedValue(0);
  const breath = useSharedValue(1);
  const tilt = useSharedValue(0);
  const pop = useSharedValue(1);
  const ringScale = useSharedValue(1);
  const ringOpacity = useSharedValue(0.3);
  const bubbleOpacity = useSharedValue(0);
  const blinkOpacity = useSharedValue(0);

  const clearBubbleTimer = useCallback(() => {
    if (bubbleTimer.current) {
      clearTimeout(bubbleTimer.current);
      bubbleTimer.current = null;
    }
  }, []);

  const showBubble = useCallback(
    (message: string, duration = 3600) => {
      clearBubbleTimer();
      setBubbleText(message);
      setBubbleMounted(true);
      bubbleOpacity.value = reduceMotion
        ? 1
        : withTiming(1, { duration: 180 });

      bubbleTimer.current = setTimeout(() => {
        if (reduceMotion) {
          bubbleOpacity.value = 0;
          setBubbleMounted(false);
          return;
        }

        bubbleOpacity.value = withTiming(
          0,
          { duration: 180 }
        );

        setTimeout(() => {
          setBubbleMounted(false);
        }, 210);
      }, duration);
    },
    [
      bubbleOpacity,
      clearBubbleTimer,
      reduceMotion,
    ]
  );

  const animateTap = useCallback(() => {
    if (reduceMotion) {
      pop.value = 1;
      return;
    }

    pop.value = withSequence(
      withTiming(0.9, { duration: 90 }),
      withSpring(1.1, {
        damping: 8,
        stiffness: 270,
      }),
      withSpring(1, {
        damping: 10,
        stiffness: 210,
      })
    );
  }, [pop, reduceMotion]);

  const triggerReaction = useCallback(
    (
      nextPose: Pose,
      message: string,
      duration = 3900
    ) => {
      const now = Date.now();

      // Avoid a noisy guide when multiple realtime events
      // arrive almost simultaneously.
      if (
        now - lastRealtimeReaction.current <
        900
      ) {
        return;
      }

      lastRealtimeReaction.current = now;

      if (reactionTimer.current) {
        clearTimeout(reactionTimer.current);
      }

      setPose(nextPose);
      animateTap();
      showBubble(message, duration);

      reactionTimer.current = setTimeout(() => {
        setPose(basePose);
      }, duration);
    },
    [
      animateTap,
      basePose,
      showBubble,
    ]
  );

  useEffect(() => {
    let active = true;

    void AccessibilityInfo.isReduceMotionEnabled()
      .then((enabled) => {
        if (active) setReduceMotion(enabled);
      })
      .catch(() => undefined);

    const subscription =
      AccessibilityInfo.addEventListener(
        'reduceMotionChanged',
        (enabled) => {
          if (active) setReduceMotion(enabled);
        }
      );

    return () => {
      active = false;
      subscription?.remove?.();
    };
  }, []);

  useEffect(() => {
    entryOpacity.value = reduceMotion
      ? 1
      : withTiming(1, { duration: 420 });
    entryY.value = reduceMotion
      ? 0
      : withSpring(0, {
          damping: 13,
          stiffness: 145,
        });

    if (reduceMotion) {
      floatY.value = 0;
      breath.value = 1;
      tilt.value = 0;
      ringScale.value = 1;
      ringOpacity.value = 0.34;
      blinkOpacity.value = 0;
      return;
    }

    floatY.value = withRepeat(
      withSequence(
        withTiming(-5, {
          duration: 1750,
          easing: Easing.inOut(Easing.quad),
        }),
        withTiming(0, {
          duration: 1750,
          easing: Easing.inOut(Easing.quad),
        })
      ),
      -1,
      false
    );

    breath.value = withRepeat(
      withSequence(
        withTiming(1.018, {
          duration: 1450,
          easing: Easing.inOut(Easing.quad),
        }),
        withTiming(1, {
          duration: 1450,
          easing: Easing.inOut(Easing.quad),
        })
      ),
      -1,
      false
    );

    tilt.value = withRepeat(
      withSequence(
        withTiming(-1.2, {
          duration: 1900,
          easing: Easing.inOut(Easing.quad),
        }),
        withTiming(1.2, {
          duration: 1900,
          easing: Easing.inOut(Easing.quad),
        })
      ),
      -1,
      true
    );

    ringScale.value = withRepeat(
      withSequence(
        withTiming(1.1, {
          duration: 1300,
          easing: Easing.out(Easing.quad),
        }),
        withTiming(1, {
          duration: 1300,
          easing: Easing.in(Easing.quad),
        })
      ),
      -1,
      false
    );

    ringOpacity.value = withRepeat(
      withSequence(
        withTiming(0.12, { duration: 1300 }),
        withTiming(0.42, { duration: 1300 })
      ),
      -1,
      false
    );

    // A tiny eyelid overlay creates an actual visible
    // blink on the idle/waving pose without a GIF.
    blinkOpacity.value = withRepeat(
      withSequence(
        withDelay(
          3000,
          withTiming(1, { duration: 55 })
        ),
        withTiming(0, { duration: 110 }),
        withDelay(
          2100,
          withTiming(0, { duration: 1 })
        )
      ),
      -1,
      false
    );

    return () => {
      cancelAnimation(floatY);
      cancelAnimation(breath);
      cancelAnimation(tilt);
      cancelAnimation(ringScale);
      cancelAnimation(ringOpacity);
      cancelAnimation(blinkOpacity);
    };
  }, [
    blinkOpacity,
    breath,
    entryOpacity,
    entryY,
    floatY,
    reduceMotion,
    ringOpacity,
    ringScale,
    tilt,
  ]);

  useEffect(() => {
    setPose(basePose);
    showBubble(routeMessage(pathname), 2600);
  }, [basePose, pathname, showBubble]);

  useEffect(() => {
    const before = previousUnread.current;

    if (unreadCount > before) {
      const added = unreadCount - before;
      triggerReaction(
        'celebrate',
        added === 1
          ? 'You have a new BUKLOD update.'
          : `You have ${added} new BUKLOD updates.`
      );
    }

    previousUnread.current = unreadCount;
  }, [triggerReaction, unreadCount]);

  useEffect(() => {
    // Prayer-aware realtime reaction. This is display-only:
    // the guide never exposes prayer text or member identity.
    const channel = supabase
      .channel('buklod-guide-prayer-activity')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'prayer_requests',
        },
        () => {
          triggerReaction(
            'think',
            'A new prayer request just came in.'
          );
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'prayer_responses',
        },
        () => {
          triggerReaction(
            'celebrate',
            'Someone just prayed with the community.'
          );
        }
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
  }, [triggerReaction]);

  useEffect(
    () => () => {
      clearBubbleTimer();

      if (reactionTimer.current) {
        clearTimeout(reactionTimer.current);
      }
    },
    [clearBubbleTimer]
  );

  const entryStyle = useAnimatedStyle(() => ({
    opacity: entryOpacity.value,
    transform: [
      { translateY: entryY.value },
    ],
  }));

  const motionStyle = useAnimatedStyle(() => ({
    transform: [
      { translateY: floatY.value },
      { rotate: `${tilt.value}deg` },
      { scale: breath.value * pop.value },
    ],
  }));

  const ringStyle = useAnimatedStyle(() => ({
    opacity: ringOpacity.value,
    transform: [
      { scale: ringScale.value },
    ],
  }));

  const bubbleStyle = useAnimatedStyle(() => ({
    opacity: bubbleOpacity.value,
    transform: [
      {
        translateY:
          (1 - bubbleOpacity.value) * 7,
      },
      {
        scale:
          0.96 +
          bubbleOpacity.value * 0.04,
      },
    ],
  }));

  const blinkStyle = useAnimatedStyle(() => ({
    opacity:
      pose === 'wave'
        ? blinkOpacity.value
        : 0,
  }));

  const onPress = () => {
    animateTap();

    if (unreadCount > 0) {
      setPose('celebrate');
      showBubble(
        `${unreadCount} unread ${
          unreadCount === 1 ? 'update' : 'updates'
        }. Opening Notifications...`,
        1200
      );

      setTimeout(() => {
        router.push('/notifications' as any);
      }, reduceMotion ? 0 : 360);

      return;
    }

    const nextPose: Pose =
      pose === 'wave'
        ? 'celebrate'
        : pose === 'celebrate'
          ? 'think'
          : basePose;

    setPose(nextPose);
    showBubble(routeMessage(pathname), 3000);

    if (reactionTimer.current) {
      clearTimeout(reactionTimer.current);
    }

    reactionTimer.current = setTimeout(() => {
      setPose(basePose);
    }, 1900);
  };

  const badgeText =
    unreadCount > 99
      ? '99+'
      : String(unreadCount);

  return (
    <Animated.View
      pointerEvents="box-none"
      style={[
        styles.floatingRoot,
        entryStyle,
      ]}
    >
      {bubbleMounted && (
        <Animated.View
          pointerEvents="none"
          style={[
            styles.bubble,
            bubbleStyle,
          ]}
        >
          <Text style={styles.bubbleEyebrow}>
            BUKLOD GUIDE
          </Text>
          <Text style={styles.bubbleText}>
            {bubbleText}
          </Text>
          <View style={styles.bubbleTail} />
        </Animated.View>
      )}

      <Pressable
        accessibilityRole="button"
        accessibilityLabel={
          unreadCount > 0
            ? `BUKLOD Guide. ${unreadCount} unread updates.`
            : 'BUKLOD Guide'
        }
        accessibilityHint={
          unreadCount > 0
            ? 'Opens the Notification Center.'
            : 'Shows a BUKLOD guide tip.'
        }
        onPress={onPress}
        hitSlop={10}
        style={styles.pressable}
      >
        <Animated.View
          pointerEvents="none"
          style={[
            styles.statusPulse,
            unreadCount > 0
              ? styles.statusPulseUnread
              : styles.statusPulseReady,
            ringStyle,
          ]}
        />

        <Animated.View
          style={[
            styles.avatarShell,
            motionStyle,
          ]}
        >
          <View
            style={[
              styles.avatarClip,
              unreadCount > 0
                ? styles.avatarClipUnread
                : styles.avatarClipReady,
            ]}
          >
            <Image
              source={GUIDE[pose]}
              style={styles.avatar}
              resizeMode="cover"
            />

            {pose === 'wave' && (
              <Animated.View
                pointerEvents="none"
                style={[
                  StyleSheet.absoluteFillObject,
                  blinkStyle,
                ]}
              >
                <View
                  style={[
                    styles.eyelid,
                    styles.leftEyelid,
                  ]}
                />
                <View
                  style={[
                    styles.eyelid,
                    styles.rightEyelid,
                  ]}
                />
              </Animated.View>
            )}
          </View>

          <View
            style={[
              styles.statusDot,
              unreadCount > 0
                ? styles.statusDotUnread
                : styles.statusDotReady,
            ]}
          />

          {unreadCount > 0 && (
            <View style={styles.badge}>
              <Text style={styles.badgeText}>
                {badgeText}
              </Text>
            </View>
          )}
        </Animated.View>
      </Pressable>
    </Animated.View>
  );
}

