'@

Write-Utf8NoBom $componentPath $componentSource

Write-Host "4/6 Mounting guide above the main tab navigation..." -ForegroundColor Yellow

$layout = Get-Content -LiteralPath $layoutPath -Raw

if ($layout -notmatch "BuklodGuideAvatar") {
    $layout =
        "import { BuklodGuideAvatar } from '@/components/BuklodGuideAvatar';`r`n" +
        $layout
}

$viewAlreadyImported =
    $layout -match '(?s)import\s*\{[^}]*\bView\b[^}]*\}\s*from\s*[''"]react-native[''"]'

if (-not $viewAlreadyImported) {
    $layout =
        "import { View } from 'react-native';`r`n" +
        $layout
}

if ($layout -notmatch "PATCH_163A_HIGH_END_BUKLOD_GUIDE") {
    $tabsStart = $layout.IndexOf("<Tabs")
    if ($tabsStart -lt 0) {
        throw "PATCH 163A stopped: <Tabs> anchor not found."
    }

    $tabsCloseStart = $layout.IndexOf("</Tabs>", $tabsStart)
    if ($tabsCloseStart -lt 0) {
        throw "PATCH 163A stopped: </Tabs> anchor not found."
    }

    $tabsCloseEnd = $tabsCloseStart + "</Tabs>".Length

    $afterTabs = @"
      {/* PATCH_163A_HIGH_END_BUKLOD_GUIDE */}
      <BuklodGuideAvatar />
    </View>
"@

    $layout = $layout.Insert(
        $tabsCloseEnd,
        "`r`n" + $afterTabs.TrimEnd()
    )

    $layout = $layout.Insert(
        $tabsStart,
        "<View style={{ flex: 1 }}>`r`n      "
    )
}

Write-Utf8NoBom $layoutPath $layout

Write-Host "5/6 Verifying installed anchors..." -ForegroundColor Yellow

$layoutVerify = Get-Content -LiteralPath $layoutPath -Raw
$componentVerify = Get-Content -LiteralPath $componentPath -Raw

$requiredLayoutMarkers = @(
    "BuklodGuideAvatar",
    "PATCH_163A_HIGH_END_BUKLOD_GUIDE",
    "<View style={{ flex: 1 }}>"
)

foreach ($marker in $requiredLayoutMarkers) {
    if ($layoutVerify -notmatch [regex]::Escape($marker)) {
        throw "PATCH 163A verification failed: missing layout marker $marker"
    }
}

$requiredComponentMarkers = @(
    "useNotifications",
    "react-native-reanimated",
    "prayer_requests",
    "prayer_responses",
    "reduceMotionChanged",
    "blinkOpacity"
)

foreach ($marker in $requiredComponentMarkers) {
    if ($componentVerify -notmatch [regex]::Escape($marker)) {
        throw "PATCH 163A verification failed: missing component marker $marker"
    }
}

Write-Host "6/6 Final TypeScript check..." -ForegroundColor Yellow
npx tsc --noEmit

if ($LASTEXITCODE -ne 0) {
    Write-Host ""
    Write-Host "TypeScript failed. Rolling back PATCH 163A..." -ForegroundColor Red

    Copy-Item -LiteralPath $layoutBackup -Destination $layoutPath -Force

    if ($componentExisted) {
        Copy-Item -LiteralPath $componentBackup -Destination $componentPath -Force
    }
    else {
        Remove-Item -LiteralPath $componentPath -Force -ErrorAction SilentlyContinue
    }

    Remove-Item -LiteralPath $assetDir -Recurse -Force -ErrorAction SilentlyContinue

    Write-Host "Rollback complete." -ForegroundColor Yellow
    throw "PATCH 163A rolled back because TypeScript did not pass."
}

Write-Host ""
Write-Host "====================================================" -ForegroundColor Green
Write-Host " PATCH 163A COMPLETE - TYPESCRIPT CLEAN" -ForegroundColor Green
Write-Host "====================================================" -ForegroundColor Green
Write-Host ""
Write-Host "INSTALLED:" -ForegroundColor Cyan
Write-Host "  - Animated BUKLOD Guide avatar"
Write-Host "  - Smooth spring entrance"
Write-Host "  - Breathing / floating idle motion"
Write-Host "  - Subtle head tilt"
Write-Host "  - Visible blink overlay"
Write-Host "  - Tap reaction + 3 character poses"
Write-Host "  - Animated status ring"
Write-Host "  - Unread notification badge"
Write-Host "  - Realtime notification reaction"
Write-Host "  - Realtime prayer request / prayer response reaction"
Write-Host "  - Context-aware tips per main tab"
Write-Host "  - Reduced-motion accessibility support"
Write-Host "  - Reusable src\components\BuklodGuideAvatar.tsx"
Write-Host ""
Write-Host "NO DATABASE PUSH REQUIRED." -ForegroundColor Green
Write-Host "Next for staging dev client:" -ForegroundColor Cyan
Write-Host "  npx expo start --dev-client -c"
Write-Host ""
